async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8");
  let buffer = "";
  let line = 1;
  let delivered = 0;

  async function handleLine(text, lineNumber) {
    if (text.endsWith("\r")) text = text.slice(0, -1);
    if (text.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error("Invalid JSON line");
      error.code = "BAD_LINE";
      error.line = lineNumber;
      throw error;
    }

    delivered++;
    return (await deliver(value, lineNumber)) !== false;
  }

  async function consumeCompleteLines() {
    let newline;
    while ((newline = buffer.indexOf("\n")) !== -1) {
      const text = buffer.slice(0, newline);
      buffer = buffer.slice(newline + 1);

      if (!(await handleLine(text, line++))) return false;
    }
    return true;
  }

  try {
    while (true) {
      const chunk = await input.read();
      if (chunk === null) break;

      buffer += decoder.decode(chunk, { stream: true });
      if (!(await consumeCompleteLines())) return delivered;
    }

    buffer += decoder.decode();

    if (!(await consumeCompleteLines())) return delivered;
    if (buffer.length > 0) await handleLine(buffer, line);

    return delivered;
  } finally {
    await input.close();
  }
}
